require "amber"

# Implement all abstract methods from QueueAdapter
class LoggingQueueAdapter < Amber::Jobs::QueueAdapter
  @inner : Amber::Jobs::MemoryQueueAdapter

  def initialize
    @inner = Amber::Jobs::MemoryQueueAdapter.new
  end

  def enqueue(envelope : Amber::Jobs::JobEnvelope) : Nil
    puts "Enqueueing #{envelope.job_class} → #{envelope.queue}"
    @inner.enqueue(envelope)
  end

  def dequeue(queue : String) : Amber::Jobs::JobEnvelope?
    @inner.dequeue(queue)
  end

  def schedule(envelope : Amber::Jobs::JobEnvelope, at : Time) : Nil
    @inner.schedule(envelope, at)
  end

  def size(queue : String) : Int32
    @inner.size(queue)
  end

  def clear(queue : String) : Nil
    @inner.clear(queue)
  end

  def mark_completed(id : String) : Nil
    @inner.mark_completed(id)
  end

  def mark_failed(id : String, error : String) : Nil
    @inner.mark_failed(id, error)
  end

  def retry_failed(id : String) : Nil
    @inner.retry_failed(id)
  end

  def dead_jobs : Array(Amber::Jobs::JobEnvelope)
    @inner.dead_jobs
  end

  def all_jobs : Array(Amber::Jobs::JobEnvelope)
    @inner.all_jobs
  end
end

# Plug in the custom adapter
Amber::Jobs.adapter = LoggingQueueAdapter.new

class RegistrationsController < Amber::Controller::Base
  def create
    validator = Amber::Validators::Params.new(raw_params)
    validator.validation do
      required(:username, "Username is required") { |v| v.size.between?(3, 30) }
      required(:email, "A valid email is required") { |v| v.includes?("@") }
      required(:password, "Password must be 8+ chars") { |v| v.size >= 8 }
      optional(:bio, "Bio too long") { |v| v.size <= 500 }
      optional(:website) { |v| v.starts_with?("http") }
    end

    unless validator.valid?
      response.status_code = 422
      render json: {errors: validator.errors.map { |e| {param: e.param, message: e.message} }}
      return
    end

    validated = validator.validate!
    User.create(validated)
    redirect_to "/login"
  end
end

