class LobbyChannel < Amber::WebSockets::Channel
  def after_join(client_socket)
    welcome = {
      "event"   => "welcome",
      "topic"   => "lobby:main",
      "payload" => {"message" => "Welcome to the lobby!"},
    }
    client_socket.socket.send(welcome.to_json)
  end

  def handle_message(client_socket, msg)
    rebroadcast!(msg)
  end
end

class ChatChannel < Amber::WebSockets::Channel
  def handle_message(client_socket, msg)
    # Forward the raw message hash to every subscriber on the same topic
    rebroadcast!({
      "event"   => msg["event"].as_s,
      "topic"   => msg["topic"].as_s,
      "payload" => msg["payload"],
    })
  end
end

struct AppSocket < Amber::WebSockets::ClientSocket
  channel "chat:*", ChatChannel

  def on_connect
    session["user_id"]? ? true : false
  end
end

class ChatChannel < Amber::WebSockets::Channel
  def handle_joined(client_socket, message)
    room_id = message["topic"]?.try(&.as_s.split(":").last)
    raise "Missing room id" unless room_id
    # Additional ACL check could go here
  end

  def after_join(client_socket)
    # Send current presence roster to the joining socket
    roster_payload = presence_list.transform_values { |meta| meta["joined_at"] }
    roster_msg = {
      "event"   => "presence_state",
      "topic"   => "chat:lobby",
      "payload" => roster_payload,
    }
    client_socket.socket.send(roster_msg.to_json)
  end

  def handle_message(client_socket, msg)
    rebroadcast!({
      "event"   => "msg:new",
      "topic"   => msg["topic"].as_s,
      "payload" => msg["payload"],
    })
  end

  def handle_leave(client_socket)
    # No custom teardown needed; presence is untracked automatically
  end

  def after_leave(client_socket)
    remaining = presence_count
    notice = {
      "event"   => "user_left",
      "topic"   => "chat:lobby",
      "payload" => {"remaining" => remaining.to_s},
    }
    broadcast!(notice)
  end

  def on_error(ex : Exception, client_socket)
    Log.error(exception: ex) { "ChatChannel error for socket #{client_socket.id}" }
  end
end
